  "claims": [
    {
      "claim": "All visible L1 gold contexts report human oral bioavailability values of at least 45% (LY2196044 45%, alfuzosin 49%, rimegepant 64%, trametinib 72%, regorafenib 69-83%, encainide 76-78%, apalutamide ~100%, safinamide 95%, MMV693183 predicted 96%), all above the 20% threshold.",
      "card_ids": ["C17","C03","C10","C12","C04","C14","C01","C05","C16"]
    },
    {
      "claim": "L3 oral exposure records for structurally related acrylamide-containing drugs (ritlecitinib, alflutinib, dacomitinib) and other lipophilic kinase inhibitors show measurable human oral AUC/Cmax, supporting that the query's acrylamide/pyrimidine chemotype can achieve oral exposure.",
      "card_ids": ["C97","C87","C96","C101","C93","C129","C118","C94"]
    },
    {
      "claim": "L4 absorption records for lipophilic amide/aryl-halide kinase inhibitors show high fraction absorbed (cobimetinib Fa 0.88 in humans, M14 >90% in rats) and good permeability (MDCK Papp 7.6), supporting that the query's lipophilic amide/pyrimidine chemotype can be absorbed.",
      "card_ids": ["C158","C166","C147","C186"]
    },
    {
      "claim": "L4 solubility records for structurally similar ibrutinib and selumetinib show poor intrinsic aqueous solubility and formulation-dependent dissolution, but these are not direct F measurements and do not affirmatively establish F<20% for the query.",
      "card_ids": ["C146","C168","C178"]
    },
    {
      "claim": "The ibrutinib low-exposure record reflects molecule-specific CYP3A first-pass metabolism; L4 ibrutinib solubility records are formulation context and do not transfer as a low-F outcome for the query.",
      "card_ids": ["C128","C146"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C158","C166","C147","C186","C146","C168","C178","C142"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental bioavailability record for the exact query molecule is present in the supplied cards.",
    "No query-specific solubility, permeability, or first-pass metabolism measurements are supplied; L4 records are for reference molecules with moderate transferability.",
    "No dose, formulation, or prandial-state information for the query is available.",
    "The ibrutinib low-exposure and poor-solubility records (C128, C146) are molecule-specific and formulation-dependent; their transfer to the query is uncertain."
  ],
  "decision_summary": "L4 intestinal absorption/solubility/permeability evidence is mixed: high measured fraction absorbed for lipophilic amide kinase inhibitors (cobimetinib Fa 0.88, M14 >90%) and good permeability support absorption, while poor intrinsic solubility for ibrutinib/selumetinib and high P-gp efflux in one reference are cautions. None of these are direct F measurements for the query, and the L1 gold contexts remain consistently above 20%. Prediction remains high with moderate confidence."
}

